    {
      "rank": 1,
      "ballot_id": "B054",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED established a powerful new regime for quantum optics, coupling controllable artificial atoms to microwave fields and enabling a major platform for quantum experiments and computing.",
        "attribution": "The listed theorists and experimentalists represent the central conceptual and experimental contributions; the credit is broad but defensible for a field built through close theory–experiment interplay.",
        "maturity": "The basic physics and its reproducibility across laboratories are well established, though the technology's ultimate computing capabilities remain under development.",
        "uncertainties": [
          "The 2025 prize for superconducting-circuit physics creates some risk of overlap; the distinction between that prize's foundational tunnelling work and circuit QED should be made explicit."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement and opened a route to clocks with extraordinary accuracy, enabling new tests of fundamental physics.",
        "attribution": "Katori's lattice-clock proposal and realization and Ye's major advances in precision and performance provide a compelling, complementary attribution.",
        "maturity": "The principle is established and replicated internationally; continued improvements strengthen rather than undermine the achievement.",
        "uncertainties": [
          "The breadth of later contributions from other clock groups complicates how to delimit the recognized foundational work."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Jean Dalibard",
        "Juan Ignacio Cirac",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments made controlled quantum simulation of many-body systems possible, joining a conceptual framework to a platform that revealed new collective quantum phenomena.",
        "attribution": "Theory and experiment are both essential, and the proposed names cover central contributions; five laureates is a large but plausible group for this broad achievement.",
        "maturity": "The platform and key phenomena have been reproduced across laboratories over many years.",
        "uncertainties": [
          "The discovery is a long, distributed development, so a narrower prize citation may be needed to make the credited contributions precise."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the essential physical framework for protecting quantum information and made fault-tolerant quantum computing a coherent scientific goal.",
        "attribution": "The proposed theorists made seminal, distinct contributions to the central ideas and codes underlying the field.",
        "maturity": "The theory is mature, and experimental demonstrations have advanced substantially, although scalable fault-tolerant operation remains unfinished.",
        "uncertainties": [
          "The prize case rests on foundational theory while its full technological consequence is still being demonstrated."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics and quantum acoustics brought increasingly massive mechanical modes under quantum control, creating a new meeting point between quantum optics and mesoscopic physics.",
        "attribution": "The named researchers represent complementary advances in devices, quantum control, and optomechanical theory and experiments.",
        "maturity": "Ground-state cooling and quantum-regime control are established, though the larger goal of testing quantum mechanics at substantially greater scales remains open.",
        "uncertainties": [
          "The discovery spans several techniques and groups, making the most distinctive prize-worthy result difficult to isolate."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computing connected a scalable gate model to exceptionally controlled physical systems and enabled some of the clearest demonstrations of quantum information processing.",
        "attribution": "Cirac and Zoller established key theoretical foundations, while Blatt's experiments provided decisive realization and control.",
        "maturity": "The platform has a long record of reproducible control and quantum gates, although large-scale fault tolerance is still ahead.",
        "uncertainties": [
          "The achievement overlaps with broader quantum-computing and quantum-simulation developments that could alter the appropriate scope of recognition."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution turned foundational quantum principles into a protocol with a distinct security basis and helped establish quantum information as an experimental field.",
        "attribution": "The proposed names capture complementary protocol and conceptual contributions, including entanglement-based and prepare-and-measure approaches.",
        "maturity": "The protocols have been extensively studied and demonstrated, while practical security and deployment still depend on device and implementation details.",
        "uncertainties": [
          "It is uncertain whether the Nobel case should be framed around a foundational physics discovery or primarily around a communications application."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed a striking route to flat bands and correlated phases in a tunable two-dimensional material, opening a major research direction.",
        "attribution": "The theoretical prediction and experimental discovery are clearly represented by Bistritzer and MacDonald and by Jarillo-Herrero.",
        "maturity": "The central observations have prompted extensive follow-up, but understanding of the phases and their relation to superconductivity continues to evolve.",
        "uncertainties": [
          "The field is comparatively young, and the durability and generality of its most consequential claims remain under active investigation."
        ]
      }
    }
  ]
